package ru.liturgyguide.service.book

/** Three independently reviewed whole prayers; optional-source presentation and meaning stay unchanged. */
internal object FeoriaThanksgivingTranslations {
    const val SOURCE_CANDIDATE_SHA256 = "0d46682c4611bd58e53372c110910619e3c490733d2ab340d5d5a158f49732b1"
    const val SEMANTIC_REVIEW_SHA256 = "13c66b5125c34444c2e30245dcbb24f003e9f92e8de7e084a28bd632c156be6b"
    const val PRIMARY_SOURCE_DOCUMENT_SHA256 = "9edee9dea1ba23d3c468b48ff8471b7641618d10e760f80f25817885f7145354"
    private const val ORIGINAL_SOURCE_URL = "https://azbyka.ru/worships/?date=2026-11-13&worship=liturgy&size=full&church=30"

    data class Record(val entry: FeoriaTranslationCatalog.Entry, val originalSha256: String,
        val normalizedOriginalSha256: String, val russianSha256: String,
        val sourceBlockId: String, val sourceChapterId: String, val printedPrayerNumber: Int)

    val records = listOf(
        Record(FeoriaTranslationCatalog.Entry("thanksgiving-949442878e936703d8eb",
            "Благодарю́ Тя́, Го́споди, Бо́же мо́й, я́ко не отри́нул мя́ еси́ гре́шнаго, но о́бщника мя́ бы́ти святы́нь Твои́х сподо́бил еси́. Благодарю́ Тя́, я́ко мене́ недосто́йнаго причасти́тися Пречи́стых Твои́х и Небе́сных Даро́в сподо́бил еси́. Но Влады́ко Человеколю́бче, на́с ра́ди уме́рый же и воскресы́й, и дарова́вый на́м стра́шная сия́ и животворя́щая Та́инства во благодея́ние и освяще́ние ду́ш и теле́с на́ших, да́ждь бы́ти си́м и мне́ во исцеле́ние души́ же и те́ла, во отгна́ние вся́каго сопроти́внаго, в просвеще́ние о́чию се́рдца моего́, в ми́р душе́вных мои́х си́л, в ве́ру непосты́дну, в любо́вь нелицеме́рну, во исполне́ние прему́дрости, в соблюде́ние за́поведей Твои́х, в приложе́ние Боже́ственныя Твоея́ благода́ти и Твоего́ Ца́рствия присвое́ние; да во святы́ни Твое́й те́ми сохраня́емь, Твою́ благода́ть помина́ю всегда́, и не к тому́ себе́ жи́ву, но Тебе́, на́шему Влады́це и Благоде́телю; и та́ко сего́ жития́ исше́д о наде́жди живота́ ве́чнаго, в присносу́щный дости́гну поко́й, иде́же пра́зднующих гла́с непреста́нный, и безконе́чная сла́дость, зря́щих Твоего́ лица́ добро́ту неизрече́нную. Ты́ бо еси́ и́стинное жела́ние, и неизрече́нное весе́лие лю́бящих Тя́, Христе́ Бо́же на́ш, и Тя́ пое́т вся́ тва́рь во ве́ки. Ами́нь.",
            "Благодарю Тебя, Господи, Боже мой, что Ты не отверг меня, грешного, но удостоил меня приобщиться к Твоим святыням. Благодарю Тебя, что Ты удостоил меня, недостойного, причаститься Твоих Пречистых и Небесных Даров. Но, Владыка, любящий людей, ради нас умерший и воскресший и даровавший нам эти внушающие благоговейный страх и животворящие Таинства на благо и освящение наших душ и тел, даруй, чтобы и для меня они послужили исцелению души и тела, изгнанию всего враждебного, просвещению очей моего сердца, умиротворению моих душевных сил, вере, которая не посрамит меня, нелицемерной любви, наполнению мудростью, соблюдению Твоих заповедей, умножению Твоей Божественной благодати во мне и приобщению к Твоему Царству. Пусть, хранимый ими в Твоей святости, я всегда помню Твою благодать и живу уже не для себя, а для Тебя, нашего Владыки и Благодетеля. И так, покинув эту жизнь с надеждой на жизнь вечную, пусть я достигну вечного покоя, где не умолкает голос празднующих и нет конца наслаждению тех, кто созерцает невыразимую красоту Твоего лица. Ведь Ты - Тот, к Кому поистине стремятся любящие Тебя, и их невыразимая радость, Христе, Боже наш, и Тебя воспевает все творение во веки. Аминь", revision = 6, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "f5fc76b1383d4e18cd1889de0df166294f31b0183f10482cf68fa0c4ab1af967",
            "949442878e936703d8eb8020fa19ec5e6f6869e1f334e02d6262abd87c97980b",
            "dde13ddcc27bd34be941ec0d5c652c56278053c509a305d01b180a15671b5bb7",
            "liturgy-7c2bf0cdfd08-1:1fd94e611400994f:1", "liturgy-7c2bf0cdfd08-1", 1),
        Record(FeoriaTranslationCatalog.Entry("thanksgiving-3833459359a0fa7639d9",
            "Те́ло Твое́ Свято́е, Го́споди, Иису́се Христе́, Бо́же на́ш, да бу́дет ми́ в живо́т ве́чный, и Кро́вь Твоя́ Честна́я во оставле́ние грехо́в: бу́ди же ми́ благодаре́ние сие́ в ра́дость, здра́вие и весе́лие; в стра́шное же и второ́е прише́ствие Твое́ сподо́би мя́ гре́шнаго ста́ти одесну́ю сла́вы Твоея́, моли́твами Пречи́стыя Твоея́ Ма́тере, и все́х святы́х.",
            "Пусть Твое Святое Тело, Господи Иисусе Христе, Боже наш, будет мне для вечной жизни, а Твоя драгоценная Кровь - для прощения грехов. Пусть это благодарение принесет мне радость, здоровье и веселье. При Твоем страшном Втором пришествии удостой меня, грешного, стать по правую сторону Твоей славы, молитвами Твоей Пречистой Матери и всех святых", revision = 6, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "0d0d00a1078a6674465c7c621dcb25d54b19da9f04cf57aea014b5563ec37fa6",
            "3833459359a0fa7639d9d21150f1fa15ca29ed182687eea6955eb7799a99bedc",
            "e20bfafe871e85ea3f688956c6ac2802d2131d811e3c1cc417a16e371cb60c72",
            "liturgy-3358761fec9f-1:ec071b826262dd30:1", "liturgy-3358761fec9f-1", 4),
        Record(FeoriaTranslationCatalog.Entry("thanksgiving-c3cc9b7d268b01a27d81",
            "Пресвята́я Влады́чице Богоро́дице, све́те помраче́нныя моея́ души́, наде́ждо, покро́ве, прибе́жище, утеше́ние, ра́дование мое́, благодарю́ Тя́, я́ко сподо́била мя́ еси́ недосто́йнаго, прича́стника бы́ти Пречи́стаго Те́ла и Честны́я Кро́ве Сы́на Твоего́. Но Ро́ждшая и́стинный Све́т, просвети́ моя́ у́мныя о́чи се́рдца; Я́же Исто́чник безсме́ртия ро́ждшая, оживотвори́ мя́ умерщвле́ннаго грехо́м; Я́же ми́лостиваго Бо́га любоблагоутро́бная Ма́ти, поми́луй мя́, и да́ждь ми́ умиле́ние и сокруше́ние в се́рдце мое́м, и смире́ние в мы́слех мои́х, и воззва́ние в плене́ниих помышле́ний мои́х; и сподо́би мя́ до после́дняго издыха́ния, неосужде́нно приима́ти пречи́стых Та́ин освяще́ние, во исцеле́ние души́ же и те́ла. И пода́ждь ми́ сле́зы покая́ния и испове́дания, во е́же пе́ти и сла́вити Тя́ во вся́ дни́ живота́ моего́, я́ко благослове́нна и препрoславленна еси́ во ве́ки. Ами́нь.",
            "Пресвятая Владычица Богородица, свет моей помраченной души, моя надежда, покров, прибежище, утешение и радость, благодарю Тебя, что Ты удостоила меня, недостойного, причаститься Пречистого Тела и драгоценной Крови Твоего Сына. Но Ты, родившая истинный Свет, просвети духовные очи моего сердца. Ты, родившая Источник бессмертия, оживи меня, умерщвленного грехом. Любящая и милосердная Мать милостивого Бога, помилуй меня и даруй мне умиление и сокрушение в сердце, смирение в мыслях и возвращение моих помыслов из плена. Удостой меня до последнего вздоха не в осуждение принимать освящение от Пречистых Таин для исцеления души и тела. И даруй мне слезы покаяния и благодарности, чтобы я воспевал и славил Тебя во все дни моей жизни, ибо Ты благословенна и безмерно прославлена во веки. Аминь", revision = 6, originalSourceUrl = ORIGINAL_SOURCE_URL),
            "9f1c6282a31a84589871ab01cd217828dedce8f46fd850e66aee211985464bd8",
            "c3cc9b7d268b01a27d817d283f9de087d94fa5521f7dc503c4deeecadd847c57",
            "e0d5f2bc71301d4eb5ca3658f6370b40e91fedf47edac8adbeeb10beff99493c",
            "liturgy-8c4444281fe9-1:b19d452896006c62:1", "liturgy-8c4444281fe9-1", 5)
    )
    val entries: List<FeoriaTranslationCatalog.Entry> = records.map { it.entry }

    init {
        require(records.size == 3 && records.map { it.entry.id }.distinct().size == 3)
        require(records.map { it.normalizedOriginalSha256 }.distinct().size == 3)
        require(records.map { it.printedPrayerNumber }.toSet() == setOf(1, 4, 5))
        require(records.all { record ->
            BookText.sha256(record.entry.original) == record.originalSha256 &&
                BookText.sha256(BookText.normalized(record.entry.original)) == record.normalizedOriginalSha256 &&
                BookText.sha256(record.entry.russian) == record.russianSha256 &&
                record.sourceBlockId.isNotBlank() && record.sourceChapterId.isNotBlank()
        })
    }
    private val byNormalizedOriginal = records.associateBy { it.normalizedOriginalSha256 }

    /** Whole lexical body only, including the original's mixed-script glyph and terminal Amen scope. */
    fun recognizes(original: String, translation: BookTranslation): Boolean {
        if (translation.source != BookTranslationIndex.FEORIA_TRANSLATION_SOURCE || translation.meaning != null) return false
        val record = byNormalizedOriginal[BookText.sha256(BookText.normalized(original))] ?: return false
        return translation.russian == record.entry.russian && BookText.sha256(translation.russian) == record.russianSha256
    }
}
